#[test]
fn rq_state_machine_valid_next_states_match_can_transition() {
    for state in WorkspaceState::all() {
        for next in state.valid_next_states() {
            assert!(
                state.can_transition_to(*next),
                "valid_next_states({state:?}) contains {next:?} but can_transition_to returns false"
            );
        }
    }
}

#[test]
fn rq_state_machine_no_surprise_valid_transitions() {
    // Every transition that can_transition says yes should also be in valid_next_states
    for from in WorkspaceState::all() {
        for to in WorkspaceState::all() {
            if from.can_transition_to(*to) {
                assert!(
                    from.valid_next_states().contains(to),
                    "can_transition({from:?}, {to:?}) is true but not in valid_next_states"
                );
            }
        }
    }
}

#[test]
fn rq_state_machine_is_active_is_complete_are_mutually_exclusive_for_terminals() {
    for state in WorkspaceState::all() {
        if state.is_terminal() {
            assert!(
                !state.is_active(),
                "Terminal state {state:?} should not be active"
            );
        }
    }
}

#[test]
fn rq_state_machine_recovery_cycle_conflict_working_conflict() {
    let s = WorkspaceState::Created;
    let s = WorkspaceStateMachine::transition(s, WorkspaceState::Working).unwrap();
    let s = WorkspaceStateMachine::transition(s, WorkspaceState::Conflict).unwrap();
    let s = WorkspaceStateMachine::transition(s, WorkspaceState::Working).unwrap();
    // Can go back to Conflict from Working
    let s = WorkspaceStateMachine::transition(s, WorkspaceState::Conflict).unwrap();
    assert!(s.is_active());
    assert!(!s.is_terminal());
}

#[test]
fn rq_state_machine_ready_to_abandoned() {
    let s = WorkspaceState::Created;
    let s = WorkspaceStateMachine::transition(s, WorkspaceState::Working).unwrap();
    let s = WorkspaceStateMachine::transition(s, WorkspaceState::Ready).unwrap();
    let s = WorkspaceStateMachine::transition(s, WorkspaceState::Abandoned).unwrap();
    assert!(s.is_terminal());
}

