fn test_ws_id() -> WorkspaceId {
    WorkspaceId::generate()
}

fn test_bead_id() -> BeadId {
    BeadId::parse("rq-bead".into()).unwrap()
}

#[test]
fn rq_guard_double_commit_fails() {
    let guard =
        WorkspaceGuard::acquire(test_ws_id(), test_bead_id(), WorkspaceState::Created).unwrap();
    let _committed = guard.commit().unwrap();
    // guard is consumed — cannot commit again (move semantics)
    // This test verifies the type system prevents double-use
}

#[test]
fn rq_guard_commit_then_abandon_type_safe() {
    let guard =
        WorkspaceGuard::acquire(test_ws_id(), test_bead_id(), WorkspaceState::Created).unwrap();
    let committed = guard.commit().unwrap();
    assert!(committed.is_ready());
    assert!(!committed.is_abandoned());
    // CommittedGuard has no commit/abandon methods — verified by type system
}

#[test]
fn rq_guard_all_non_created_states_rejected() {
    let non_created = [
        WorkspaceState::Working,
        WorkspaceState::Ready,
        WorkspaceState::Merged,
        WorkspaceState::Abandoned,
        WorkspaceState::Conflict,
    ];
    for state in &non_created {
        let result = WorkspaceGuard::acquire(test_ws_id(), test_bead_id(), *state);
        assert!(result.is_err(), "acquire with {state:?} should fail");
    }
}

#[test]
fn rq_guard_mapping_bead_matches() {
    let ws_id = WorkspaceId::parse("ws-rq-1".into()).unwrap();
    let bead_id = BeadId::parse("bead-rq-1".into()).unwrap();
    let guard =
        WorkspaceGuard::acquire(ws_id.clone(), bead_id.clone(), WorkspaceState::Created).unwrap();
    let mapping = guard.mapping().unwrap();
    assert_eq!(mapping.bead_id(), &bead_id);
    assert_eq!(mapping.workspace_id(), &ws_id);
}

#[test]
fn rq_guard_workspace_id_generate_format() {
    let id = WorkspaceId::generate();
    let s = id.as_str();
    assert!(s.starts_with("iso-"));
    // Format: iso-{timestamp}-{counter}
    let parts: Vec<&str> = s.split('-').collect();
    assert!(parts.len() >= 3, "expected at least 3 parts in '{s}'");
}

#[test]
fn rq_committed_guard_round_trip_commit() {
    let ws_id = test_ws_id();
    let bead_id = test_bead_id();
    let guard =
        WorkspaceGuard::acquire(ws_id.clone(), bead_id.clone(), WorkspaceState::Created).unwrap();
    let committed = guard.commit().unwrap();
    let cloned = committed.clone();
    assert_eq!(committed.workspace_id(), cloned.workspace_id());
    assert_eq!(committed.bead_id(), cloned.bead_id());
    assert_eq!(committed.state(), cloned.state());
}

#[test]
fn rq_committed_guard_round_trip_abandon() {
    let ws_id = test_ws_id();
    let bead_id = test_bead_id();
    let guard =
        WorkspaceGuard::acquire(ws_id.clone(), bead_id.clone(), WorkspaceState::Created).unwrap();
    let committed = guard.abandon().unwrap();
    assert!(committed.is_abandoned());
    assert!(!committed.is_ready());
    assert!(committed.state().is_terminal());
}

#[test]
fn rq_bead_workspace_mapping_timestamp_reasonable() {
    let before = chrono::Utc::now();
    let mapping = BeadWorkspaceMapping::new(
        BeadId::parse("b".into()).unwrap(),
        WorkspaceId::parse("w".into()).unwrap(),
    );
    let after = chrono::Utc::now();
    assert!(mapping.assigned_at() >= before);
    assert!(mapping.assigned_at() <= after);
}

