    // All names are unique
    let mut names: Vec<&str> = events.iter().map(|(n, _)| *n).collect();
    names.sort();
    let deduped: std::collections::HashSet<&str> = names.iter().copied().collect();
    assert_eq!(names.len(), deduped.len(), "event names should be unique");
