#[test]
fn rq_event_type_classification_completeness() {
    // Every event variant must classify into exactly one EventType
    let mut event_type_counts = std::collections::HashMap::new();
    let events: Vec<IsolateEvent> = vec![
        IsolateEvent::WorkspaceCreated {
            name: "w".into(),
            source: "s".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::WorkspaceActivated {
            name: "w".into(),
            state: WorkspaceState::Working,
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::WorkspaceSyncing {
            name: "w".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::WorkspaceSynced {
            name: "w".into(),
            commits_rebased: 0,
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::WorkspacePaused {
            name: "w".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::WorkspaceResumed {
            name: "w".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::WorkspaceCompleted {
            name: "w".into(),
            branch: "b".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::WorkspaceFailed {
            name: "w".into(),
            reason: "r".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::SessionStarted {
            name: "w".into(),
            session_id: "s".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::SessionEnded {
            name: "w".into(),
            session_id: "s".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::AgentClaimed {
            name: "w".into(),
            agent_id: "a".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::AgentReleased {
            name: "w".into(),
            agent_id: "a".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::BranchCreated {
            name: "w".into(),
            branch: "b".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::BranchPushed {
            name: "w".into(),
            branch: "b".into(),
            commits: 0,
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::RebaseCompleted {
            name: "w".into(),
            commits: 0,
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::ConflictDetected {
            name: "w".into(),
            files: vec![],
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
        IsolateEvent::ConflictResolved {
            name: "w".into(),
            context: rq_ctx("w"),
            timestamp: rq_now(),
        },
    ];

    for e in &events {
        let et = e.event_type();
        *event_type_counts
            .entry(format!("{:?}", et))
            .or_insert(0usize) += 1;
    }

    assert_eq!(
        *event_type_counts.get("WorkspaceLifecycle").unwrap_or(&0),
        8
    );
    assert_eq!(*event_type_counts.get("Session").unwrap_or(&0), 2);
    assert_eq!(*event_type_counts.get("Agent").unwrap_or(&0), 2);
    assert_eq!(*event_type_counts.get("Vcs").unwrap_or(&0), 5);
}

