#[test]
fn rq_dag_cycle_a_b_a_detected() {
    let mut dag = BranchDag::new();
    dag.add_branch(BranchId::new("a"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(BranchId::new("b"), vec![BranchId::new("a")])
        .unwrap();
    let result = dag.add_branch(BranchId::new("a"), vec![BranchId::new("b")]);
    // "a" already exists so it's BranchAlreadyExists, not CycleDetected
    assert!(result.is_err());
}

#[test]
fn rq_dag_trunk_cannot_be_added() {
    let mut dag = BranchDag::new();
    let result = dag.add_branch(BranchId::new("trunk"), vec![]);
    assert!(matches!(result, Err(DagError::BranchAlreadyExists(_))));
}

#[test]
fn rq_dag_trunk_can_be_removed_when_no_descendants() {
    let mut dag = BranchDag::new();
    let result = dag.remove_branch(BranchId::new("trunk"));
    // trunk has no descendants, so removal succeeds
    assert!(
        result.is_ok(),
        "trunk should be removable when it has no descendants"
    );
    // After removing trunk, DAG has 0 branches
    assert_eq!(dag.len(), 0);
    // is_empty() checks len == 1 (trunk only), so with 0 branches it returns false
    assert!(!dag.is_empty() || dag.len() == 0);
}

#[test]
fn rq_dag_deep_diamond_pattern() {
    let mut dag = BranchDag::new();
    // trunk -> a, b -> c -> d
    dag.add_branch(BranchId::new("a"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(BranchId::new("b"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(
        BranchId::new("c"),
        vec![BranchId::new("a"), BranchId::new("b")],
    )
    .unwrap();
    dag.add_branch(BranchId::new("d"), vec![BranchId::new("c")])
        .unwrap();

    let order = dag.topological_sort().unwrap();
    assert_eq!(order.len(), 5);

    let trunk_pos = order
        .iter()
        .position(|id| id == &BranchId::new("trunk"))
        .unwrap();
    let a_pos = order
        .iter()
        .position(|id| id == &BranchId::new("a"))
        .unwrap();
    let b_pos = order
        .iter()
        .position(|id| id == &BranchId::new("b"))
        .unwrap();
    let c_pos = order
        .iter()
        .position(|id| id == &BranchId::new("c"))
        .unwrap();
    let d_pos = order
        .iter()
        .position(|id| id == &BranchId::new("d"))
        .unwrap();

    assert!(trunk_pos < a_pos);
    assert!(trunk_pos < b_pos);
    assert!(a_pos < c_pos);
    assert!(b_pos < c_pos);
    assert!(c_pos < d_pos);
}

#[test]
fn rq_dag_ancestors_diamond() {
    let mut dag = BranchDag::new();
    dag.add_branch(BranchId::new("a"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(BranchId::new("b"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(
        BranchId::new("c"),
        vec![BranchId::new("a"), BranchId::new("b")],
    )
    .unwrap();

    let ancestors = dag.ancestors(&BranchId::new("c")).unwrap();
    assert_eq!(ancestors.len(), 3); // trunk, a, b
    assert!(ancestors.contains(&BranchId::new("trunk")));
    assert!(ancestors.contains(&BranchId::new("a")));
    assert!(ancestors.contains(&BranchId::new("b")));
}

#[test]
fn rq_dag_descendants_diamond() {
    let mut dag = BranchDag::new();
    dag.add_branch(BranchId::new("a"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(BranchId::new("b"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(
        BranchId::new("c"),
        vec![BranchId::new("a"), BranchId::new("b")],
    )
    .unwrap();

    let desc = dag.descendants(&BranchId::new("trunk")).unwrap();
    assert_eq!(desc.len(), 3);
    assert!(desc.contains(&BranchId::new("a")));
    assert!(desc.contains(&BranchId::new("b")));
    assert!(desc.contains(&BranchId::new("c")));
}

#[test]
fn rq_dag_remove_leaf_then_parent() {
    let mut dag = BranchDag::new();
    dag.add_branch(BranchId::new("a"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(BranchId::new("b"), vec![BranchId::new("a")])
        .unwrap();

    // Remove leaf first
    dag.remove_branch(BranchId::new("b")).unwrap();
    assert!(!dag.contains(&BranchId::new("b")));

    // Now parent has no descendants, can be removed
    dag.remove_branch(BranchId::new("a")).unwrap();
    assert!(!dag.contains(&BranchId::new("a")));
    assert_eq!(dag.len(), 1);
}

#[test]
fn rq_dag_branch_ids_always_sorted() {
    let mut dag = BranchDag::new();
    let names = ["z", "m", "a", "f", "c"];
    for name in &names {
        dag.add_branch(BranchId::new(*name), vec![BranchId::new("trunk")])
            .unwrap();
    }
    let ids = dag.branch_ids();
    let mut sorted = ids.clone();
    sorted.sort();
    assert_eq!(ids, sorted, "branch_ids() must return sorted order");
}

#[test]
fn rq_dag_empty_topo_sort_fails() {
    // New DAG has trunk, so remove it first to get truly empty
    let mut dag = BranchDag::new();
    dag.remove_branch(BranchId::new("trunk")).ok();
    let result = dag.topological_sort();
    assert!(matches!(result, Err(DagError::EmptyDag)));
}

#[test]
fn rq_dag_path_to_root_diamond() {
    let mut dag = BranchDag::new();
    dag.add_branch(BranchId::new("a"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(BranchId::new("b"), vec![BranchId::new("trunk")])
        .unwrap();
    dag.add_branch(
        BranchId::new("c"),
        vec![BranchId::new("a"), BranchId::new("b")],
    )
    .unwrap();

    let path = dag.path_to_root(&BranchId::new("c")).unwrap();
    assert_eq!(path[0], BranchId::new("c"));
    // First parent in the list determines the path
    assert!(path.contains(&BranchId::new("a")));
    assert!(path.contains(&BranchId::new("trunk")));
    assert!(path.last().unwrap() == &BranchId::new("trunk"));
}

#[test]
fn rq_dag_wide_fan_out() {
    let mut dag = BranchDag::new();
    for i in 0..20 {
        dag.add_branch(
            BranchId::new(format!("branch-{i}")),
            vec![BranchId::new("trunk")],
        )
        .unwrap();
    }
    assert_eq!(dag.len(), 21);
    let desc = dag.descendants(&BranchId::new("trunk")).unwrap();
    assert_eq!(desc.len(), 20);
}

#[test]
fn rq_dag_deep_chain_ancestors() {
    let mut dag = BranchDag::new();
    let depth = 10;
    let mut prev = "trunk".to_string();
    for i in 0..depth {
        let name = format!("b{i}");
        dag.add_branch(BranchId::new(&name), vec![BranchId::new(&prev)])
            .unwrap();
        prev = name;
    }

    let leaf = format!("b{}", depth - 1);
    let ancestors = dag.ancestors(&BranchId::new(&leaf)).unwrap();
    assert_eq!(ancestors.len(), depth);
    assert!(ancestors.contains(&BranchId::new("trunk")));
}

